const PHOTO='https://upload.wikimedia.org/wikipedia/commons/d/de/Smooth_Dachshund_red_and_tan_portrait.jpg';
const main=document.getElementById('main');
const icon=(name)=>{const paths={home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',pet:'<circle cx="7" cy="6" r="2"/><circle cx="17" cy="6" r="2"/><circle cx="4" cy="12" r="2"/><circle cx="20" cy="12" r="2"/><path d="M6 20c-3-4 3-10 6-10s9 6 6 10c-2 2-4-1-6-1s-4 3-6 1z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18"/>',heart:'<path d="M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-6 5 2 12 8 17 6-5 14-12 8-17z"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-4c0-6 14-6 14 0v4M17 4c6 1 6 8 0 9M19 15c3 1 3 3 3 6"/>',chart:'<path d="M3 3v18h18M7 16l4-5 4 2 6-8"/>',file:'<path d="M5 2h9l5 5v15H5zM14 2v6h5M8 12h8M8 16h8"/>',check:'<path d="m5 12 4 4L20 5"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',bell:'<path d="M4 17h16l-3-4V8a5 5 0 0 0-10 0v5zM10 21h4"/>',arrow:'<path d="m8 4 8 8-8 8"/>'};return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.file}</svg>`};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const header=(eyebrow,title,subtitle,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const KEY='omp-prototype-v1';
const seed=()=>({pets:[{id:'luke',name:'Luke',species:'Perro',breed:'Dachshund',age:'4 años (aproximada)',sex:'Macho',chip:'Registrado · No público',sterilized:'Sí',photo:PHOTO},{id:'sansa',name:'Sansa',species:'Perro',breed:'Mezcla',age:'3 años (aproximada)',sex:'Hembra',chip:'Sin registrar',sterilized:'Sí',photo:''}],records:[{id:'r1',pet:'luke',title:'Control preventivo',date:'2026-09-28',type:'Consulta',source:'clinic',author:'Dra. Andrea Torres',text:'Registro de demostración. Se revisaron los antecedentes y se acordó una visita de seguimiento.',plan:'Coordinar el próximo control con la clínica.',weight:'15.2',changes:[{date:'28 sep 2026',author:'Dra. Andrea Torres',text:'Registro creado'}]},{id:'r2',pet:'luke',title:'Observación en casa',date:'2026-09-30',type:'Observación',source:'tutor',author:'Camilo Martínez',text:'Luke completó su paseo habitual y comió como de costumbre.',plan:'',changes:[{date:'30 sep 2026',author:'Camilo Martínez',text:'Anotación creada'}]}],documents:[{id:'d1',pet:'luke',name:'Constancia de vacunación · Ejemplo',issuer:'Veterinaria Los Olivos',date:'2026-09-28',verified:true,local:false}],measurements:[{pet:'luke',date:'2026-07-01',type:'Peso',value:14.8,unit:'kg',source:'Clínica'},{pet:'luke',date:'2026-08-01',type:'Peso',value:15,unit:'kg',source:'Clínica'},{pet:'luke',date:'2026-09-28',type:'Peso',value:15.2,unit:'kg',source:'Clínica'}],reminders:[{id:'care1',pet:'luke',title:'Cuidado indicado por la clínica',time:'20:00',start:'2026-10-05',end:'2026-10-12',active:true,done:false,by:'',source:'clinic'}],appointments:[],family:[{id:'f1',name:'Camilo Martínez',role:'Administrador',status:'Activo'},{id:'f2',name:'Paula Martínez',role:'Cuidador',status:'Activo'}],links:[],alerts:[],automations:{visits:true,followup:false},prefs:{push:true,email:true,quiet:true,contrast:false,dark:false,scale:'100',pet:'all'},plan:'Prueba',offline:false,queue:0,audit:[],wellness:0});
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved?.pets&&saved?.prefs?saved:seed()}catch{state=seed()}
let role='tutor',route=location.hash.slice(1)||'hoy',selectedPet=state.pets[0].id,tab='resumen',recordFilter='all',query='',actor='Camilo Martínez',measureType='Peso';let timer;
const pet=()=>state.pets.find(p=>p.id===selectedPet)||state.pets[0];
const petName=id=>state.pets.find(p=>p.id===id)?.name||'Mascota';
const stamp=()=>new Date().toLocaleString('es-CL',{timeZone:'America/Santiago'});
const dateFmt=s=>new Date(s+'T12:00:00').toLocaleDateString('es-CL',{day:'numeric',month:'short',year:'numeric'});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function persist(message){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('El navegador no pudo guardar los cambios. Puedes continuar durante esta sesión.')}if(message)toast(message)}
function audit(text){state.audit.unshift({date:stamp(),author:role==='clinic'?'Dra. Andrea Torres':actor,text});if(state.offline)state.queue++}
function toast(text){clearTimeout(timer);const el=document.getElementById('toast');el.textContent=text;el.style.display='block';timer=setTimeout(()=>el.style.display='none',4500)}
function modal(title,body){document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-body').innerHTML=body;const d=document.getElementById('dialog');if(!d.open)d.showModal()}
function close(){document.getElementById('dialog').close()}
function go(path){if(route===path){render();return}location.hash=path}
const formEnd=(label='Guardar')=>`<div class="form-actions">${btn('Cancelar','cancel')}<button class="primary" type="submit">${label}</button></div>`;
const options=(items,selected='')=>items.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('');
const petOptions=()=>state.pets.map(p=>`<option value="${p.id}" ${p.id===selectedPet?'selected':''}>${esc(p.name)}</option>`).join('');
const avatar=(p,large=false)=>p.photo?`<img class="pet-image ${large?'large':''}" src="${esc(p.photo)}" alt="${esc(p.name)}, foto de perfil">`:`<div class="avatar ${large?'large':''}" aria-label="${esc(p.name)}">${esc(p.name.slice(0,2).toUpperCase())}</div>`;
function render(){
 const nav=role==='clinic'?[['panel','chart','Resumen'],['agenda','calendar','Agenda'],['pacientes','pet','Pacientes'],['automatizaciones','bell','Seguimientos'],['planes','file','Planes']]:[['hoy','home','Hoy'],['mascotas','pet','Mascotas'],['clinica','calendar','Mi clínica'],['familia','users','Familia'],['ayuda','heart','Ayuda']];
 if(!nav.some(n=>n[0]===route))route=nav[0][0];
 document.getElementById('nav').innerHTML=nav.map(([path,i,label])=>`<a href="#${path}" class="${path===route?'active':''}" ${path===route?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('');
 document.querySelector('.sidebar-bottom').innerHTML=role==='clinic'?'<span class="avatar mini">AT</span><div>Dra. Andrea Torres<small>Veterinaria Los Olivos</small></div>':'<span class="avatar mini">CM</span><div>Camilo Martínez<small>Familia de '+esc(pet().name)+'</small></div>';
 document.getElementById('breadcrumb').textContent=(role==='clinic'?'Los Olivos':'Tu espacio')+' / '+nav.find(n=>n[0]===route)[2];
 document.body.classList.toggle('theme-dark',state.prefs.dark);document.body.classList.toggle('high-contrast',state.prefs.contrast);document.documentElement.style.fontSize=Number(state.prefs.scale)/100*16+'px';
 document.getElementById('connection').textContent=state.offline?`Sin conexión · ${state.queue} pendientes`:'En línea';document.getElementById('connection').classList.toggle('offline',state.offline);
 const screens={hoy:home,mascotas:pets,clinica:clinic,familia:family,ayuda:help,panel:panel,agenda:agenda,pacientes:patients,automatizaciones:automations,planes:plans};
 main.innerHTML=(state.offline?'<div class="notice warning">Modo sin conexión de ejemplo. Puedes consultar datos y guardar cambios locales. Las solicitudes externas esperan a la reconexión.</div>':'')+screens[route]();
}
function home(){const p=pet();const r=state.reminders.filter(r=>r.pet===p.id);const a=state.appointments.filter(a=>a.pet===p.id).slice(-1)[0];return header('TU PLAN DE CUIDADOS','Cuidar empieza por hoy','Tu próximo paso, sin perder de vista lo importante.',btn('Agregar mascota','add-pet','primary'))+`<div class="grid"><div><section class="card feature">${avatar(p)}<div><span class="small">TU COMPAÑERO</span><h2>${esc(p.name)} está en buenas manos</h2><p class="small">Organiza sus cuidados y compártelos con tu familia.</p>${btn('Ver su historial','profile','primary')}</div></section><section class="card"><div class="section-title"><h2>Próximos cuidados</h2><span class="badge">${r.filter(x=>!x.done&&x.active).length+(!a?1:0)} pendientes</span></div><div class="task"><div class="date-block">${a?new Date(a.date+'T12:00:00').toLocaleDateString('es-CL',{month:'short'}).toUpperCase():'OCT'}<strong>${a?a.date.slice(-2):'08'}</strong></div><div class="task-info"><h3>Control preventivo</h3><p class="muted small">${esc(p.name)} · Veterinaria Los Olivos</p><span class="badge ${!a?'orange':''}">${a?esc(a.status):'Falta solicitar hora'}</span>${a?`<p class="small" style="margin-top:8px">${dateFmt(a.date)} · ${esc(a.time)}</p>`:''}<div class="actions">${a?btn('Ver solicitud','appointments'):btn('Solicitar hora','booking','primary')}${btn('Ver indicaciones','profile')}</div></div></div>${r.map(x=>`<div class="task"><div class="date-block">HOY<strong>${esc(x.time.slice(0,2))}h</strong></div><div class="task-info"><h3>${esc(x.title)}</h3><p class="muted small">${esc(p.name)} · ${x.source==='clinic'?'Plan registrado por la clínica':'Recordatorio del tutor'}</p>${x.done?`<span class="badge">Realizado por ${esc(x.by)}</span>`:!x.active?'<span class="badge neutral">En pausa</span>':''}<div class="actions">${!x.done&&x.active?btn('Marcar realizado','complete','secondary',`data-id="${x.id}"`):''}${btn('Configurar','reminder','',`data-id="${x.id}"`)}</div></div></div>`).join('')}</section><section class="card"><div class="section-title"><h2>Hábitos de bienestar</h2><span class="badge neutral">Opcional</span></div><p class="muted small">Registra una actividad compartida. Sin clasificaciones ni competencia.</p><div class="row space"><span>${state.wellness} actividades registradas</span>${btn('Registrar actividad','wellness')}</div></section></div><div><section class="card"><h2>Todo a mano</h2>${btn('Historial y documentos','profile','list-link')}${btn('Coordinar con mi clínica','booking','list-link')}${btn('Compartir con la familia','family','list-link')}${btn('Reportar un extravío','lost','list-link')}</section><section class="card"><span class="eyebrow">TU CLÍNICA</span><h3 style="margin-top:12px">Veterinaria Los Olivos</h3><p class="muted small">Perfil de ejemplo · Atención coordinada</p>${btn('Solicitar una hora','booking','primary')}</section><section class="card"><h3>Tu información te acompaña</h3><p class="muted small">Descarga un resumen o comparte solo lo que decidas.</p>${btn('Compartir resumen','share','secondary')}</section></div></div>`}
function petOverview(){
 const p=pet();
 const appointments=state.appointments.filter(a=>a.pet===p.id&&a.status!=='Cancelada'&&a.date>=today()).sort((a,b)=>a.date.localeCompare(b.date));
 const next=appointments[0];
 const reminders=state.reminders.filter(r=>r.pet===p.id&&r.active&&!r.done&&r.end>=today());
 const last=state.records.filter(r=>r.pet===p.id&&r.source==='clinic').sort((a,b)=>b.date.localeCompare(a.date))[0];
 const docs=state.documents.filter(d=>d.pet===p.id);
 return `<div class="pet-overview"><section class="card next-step"><div class="eyebrow">SU SIGUIENTE PASO</div><h2>${next?next.status==='Confirmada'?'Próxima visita de '+esc(p.name):'Tu solicitud está en revisión':'Coordinar el próximo cuidado'}</h2><p>${next?dateFmt(next.date)+' · '+esc(next.time)+' · '+esc(next.reason):last?.plan?esc(last.plan):'Consulta con tu clínica qué cuidados corresponden a '+esc(p.name)+'.'}</p><span class="badge ${next?.status==='Confirmada'?'':'orange'}">${next?esc(next.status):'Fecha por confirmar'}</span><div class="actions">${next?btn('Ver solicitud','appointments','primary'):btn('Solicitar hora para '+esc(p.name),'booking','primary')}${last?btn('Revisar indicaciones','record','',`data-id="${last.id}"`):''}</div></section><section class="card"><div class="section-title"><h2>Cuidados de ${esc(p.name)}</h2>${btn('Ver todos','tab','text-button','data-id="cuidados"')}</div>${reminders.length?reminders.slice(0,2).map(r=>`<div class="task"><div class="date-block">${r.start>today()?'DESDE':'AVISO'}<strong>${esc(r.time)}</strong></div><div class="task-info"><h3>${esc(r.title)}</h3><p class="small muted">${r.start>today()?dateFmt(r.start):'Dentro del periodo de cuidado'} · Hasta ${dateFmt(r.end)}</p><div class="actions">${btn('Marcar realizado','complete','secondary',`data-id="${r.id}"`)}${btn('Configurar aviso','reminder','text-button',`data-id="${r.id}"`)}</div></div></div>`).join(''):`<p class="muted">No tienes recordatorios activos pendientes para ${esc(p.name)}.</p><p class="small muted">Esto describe los avisos registrados, no el estado de salud de tu mascota.</p>${btn('Añadir recordatorio','new-reminder','secondary')}`}</section><section class="card"><div class="section-title"><h2>Última consulta</h2>${btn('Ver historial','tab','text-button','data-id="historial"')}</div>${last?`<h3>${esc(last.title)}</h3><p>${esc(last.text)}</p>${last.plan?`<div class="soft-block"><strong>Qué sigue</strong><p>${esc(last.plan)}</p></div>`:''}<p class="small muted">${dateFmt(last.date)} · ${esc(last.author)} <span class="badge">Clínica</span></p>${btn('Abrir consulta','record','',`data-id="${last.id}"`)}`:`<p class="muted">Aún no hay consultas compartidas por la clínica.</p>${btn('Pedir antecedentes','message','secondary')}`}</section><section class="card"><h2>Para acompañar sus cuidados</h2><p class="muted">${docs.length?docs.length+' documento'+(docs.length===1?'':'s')+' en su perfil.':'Todavía no tienes documentos en su perfil.'}</p><div class="actions">${btn('Ver documentos','tab','', 'data-id="documentos"')}${btn('Añadir observación','note','secondary')}${btn('Compartir resumen','share')}</div></section></div>`;
}
function petInformation(){const p=pet();return `<section class="card profile-information"><div class="section-title"><h2>Información de ${esc(p.name)}</h2>${btn('Editar información','edit-pet','secondary')}</div><dl><div><dt>Especie</dt><dd>${esc(p.species)}</dd></div><div><dt>Raza o mezcla</dt><dd>${esc(p.breed||'Sin indicar')}</dd></div><div><dt>Edad</dt><dd>${esc(p.age||'Sin indicar')}</dd></div><div><dt>Sexo</dt><dd>${esc(p.sex||'Sin indicar')}</dd></div><div><dt>Esterilización</dt><dd>${esc(p.sterilized||'Sin indicar')}</dd></div><div><dt>Microchip · Privado</dt><dd>${esc(p.chip||'Sin registrar')}</dd></div></dl><p class="small muted">La información administrativa permanece aquí para consultarla o editarla cuando la necesites.</p></section>`}
function pets(){
 const p=pet();
 if(tab==='mediciones')tab='cuidados';
 return `<section class="pet-hero" aria-labelledby="pet-title"><div class="pet-identity">${avatar(p)}<div><div class="eyebrow">MIS MASCOTAS / PERFIL</div><h1 id="pet-title">${esc(p.name)}</h1><p>${esc(p.species)} · ${esc(p.breed||'Raza o mezcla no indicada')} · ${esc(p.age||'Edad no indicada')}</p><p class="small muted">Sus cuidados y antecedentes</p></div></div><div class="pet-hero-actions"><label for="pet-switch">Estás visitando a<select id="pet-switch">${petOptions()}</select></label><div class="actions">${btn('Información','tab','text-button','data-id="informacion"')}${btn('Editar perfil','edit-pet','text-button')}</div></div></section><div class="pet-context-bar"><div class="pet-context-identity">${avatar(p)}<strong>${esc(p.name)}</strong></div><nav class="pet-section-tabs" aria-label="Secciones de ${esc(p.name)}">${[['resumen','Resumen'],['cuidados','Cuidados'],['historial','Historial'],['documentos','Documentos']].map(([id,label])=>btn(label,'tab',tab===id?'active':'',`data-id="${id}" aria-pressed="${tab===id}"`)).join('')}</nav></div><div class="pet-section-content" id="pet-section-content">${({resumen:petOverview,cuidados:()=>care()+`<details class="card measurements-details"><summary>Mediciones y evolución de ${esc(p.name)}</summary>${measurements()}</details>`,historial:history,documentos:documents,informacion:petInformation}[tab]||petOverview)()}</div>`;
}
function history(){const items=state.records.filter(r=>r.pet===selectedPet&&(recordFilter==='all'||r.source===recordFilter)&&r.title.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="section-heading"><h2>La historia de ${esc(pet().name)}</h2><p class="muted">Qué ocurrió, qué sigue y quién registró cada cuidado.</p></div><div class="filters"><input id="history-search" aria-label="Buscar en el historial" placeholder="Buscar una consulta u observación" value="${esc(query)}"><select id="history-filter" aria-label="Origen del registro"><option value="all" ${recordFilter==='all'?'selected':''}>Todos los registros</option><option value="clinic" ${recordFilter==='clinic'?'selected':''}>Registrados por clínica</option><option value="tutor" ${recordFilter==='tutor'?'selected':''}>Añadidos por tutor</option></select>${btn('Añadir observación','note','secondary')}</div>${items.length?`<div class="timeline">${items.map(r=>`<article class="card event"><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p>${r.plan?`<div class="soft-block"><strong>Qué sigue</strong><p>${esc(r.plan)}</p></div>`:''}<div class="record-provenance"><span class="badge ${r.source==='tutor'?'neutral':''}">${r.source==='clinic'?'Registrado por la clínica':'Añadido por el tutor'}</span><span class="small muted">${dateFmt(r.date)} · ${esc(r.author)}</span></div><div class="actions">${btn('Ver consulta completa','record','',`data-id="${r.id}"`)}${btn('Ver cambios','audit-record','text-button',`data-id="${r.id}"`)}${r.source==='tutor'?btn('Editar observación','edit-note','text-button',`data-id="${r.id}"`):''}</div></article>`).join('')}</div>`:empty('Aún no hay registros','Añade una observación o solicita a tu clínica que comparta la consulta.','Añadir observación','note')}`}
function care(){const reminders=state.reminders.filter(r=>r.pet===selectedPet);return `<section class="card"><div class="section-title"><h2>Vacunas y prevención</h2>${btn('Solicitar hora','booking','secondary')}</div><div class="task"><div class="avatar">V</div><div><h3>Revisión del plan de vacunación</h3><p class="small muted">La clínica confirma las próximas fechas según los antecedentes.</p><span class="badge orange">Fecha por confirmar</span></div></div><div class="task"><div class="avatar">P</div><div><h3>Prevención y desparasitación</h3><p class="small muted">Consulta las indicaciones registradas por tu veterinaria.</p>${btn('Consultar plan','message','text-button')}</div></div></section><section class="card"><div class="section-title"><h2>Recordatorios</h2>${btn('Crear recordatorio','new-reminder','secondary')}</div>${reminders.length?reminders.map(r=>`<div class="task"><div class="task-info"><h3>${esc(r.title)}</h3><p class="small muted">${esc(r.time)} · ${dateFmt(r.start)} a ${dateFmt(r.end)}</p><span class="badge ${!r.active?'neutral':''}">${r.done?'Realizado por '+esc(r.by):r.active?'Activo':'En pausa'}</span><div class="actions">${btn('Configurar','reminder','',`data-id="${r.id}"`)}${!r.done&&r.active?btn('Marcar realizado','complete','secondary',`data-id="${r.id}"`):''}</div></div></div>`).join(''):empty('Sin recordatorios','Crea uno para un cuidado o una indicación ya recibida.','Crear recordatorio','new-reminder')}</section>`}
function documents(){const docs=state.documents.filter(d=>d.pet===selectedPet);return `<section class="card"><div class="section-title"><h2>Documentos y certificados</h2>${btn('Añadir documento','upload','secondary')}</div>${docs.map(d=>`<div class="file-item"><div class="row space"><h3>${esc(d.name)}</h3><span class="badge ${d.verified?'':'neutral'}">${d.verified?'Emisor de ejemplo':'Sin validar'}</span></div><p class="small muted">${esc(d.issuer)} · ${dateFmt(d.date)}</p><div class="actions">${btn('Ver documento','document','',`data-id="${d.id}"`)}${d.verified?btn('Consultar procedencia','verify','text-button',`data-id="${d.id}"`):''}</div></div>`).join('')||'<p class="muted">Aún no tienes documentos.</p>'}<p class="small muted" style="margin-top:16px">Los originales seleccionados se pueden consultar durante esta sesión. No se envían a ningún servidor.</p></section><section class="card"><h3>Un resumen que puedes llevar contigo</h3><p class="muted small">Exporta los datos o prepara un resumen imprimible de tu mascota.</p><div class="actions">${btn('Descargar datos','export')}${btn('Imprimir resumen / PDF','print-summary','secondary')}</div></section>`}
function measurements(){const items=state.measurements.filter(m=>m.pet===selectedPet&&m.type===measureType).sort((a,b)=>a.date.localeCompare(b.date));const units={Peso:'kg',Temperatura:'°C','Frecuencia cardíaca':'lat/min',Respiración:'resp/min'};let chart='';if(items.length>1){const values=items.map(m=>Number(m.value));const min=Math.min(...values)-.2,max=Math.max(...values)+.2;const xs=items.map((m,i)=>65+i*420/(items.length-1));const ys=values.map(v=>130-(v-min)/(max-min)*100);chart=`<svg class="sparkline" viewBox="0 0 550 180" role="img" aria-label="${esc(measureType)}: ${items.map(m=>esc(m.value)+' '+units[measureType]+' el '+dateFmt(m.date)).join(', ')}"><path d="M55 20V140H510" fill="none" stroke="var(--line)"/><polyline points="${xs.map((x,i)=>x+','+ys[i]).join(' ')}" fill="none" stroke="var(--brand)" stroke-width="3"/>${items.map((m,i)=>`<circle cx="${xs[i]}" cy="${ys[i]}" r="4" fill="var(--brand)"/><text x="${xs[i]}" y="${ys[i]-12}" text-anchor="middle">${esc(m.value)} ${units[measureType]}</text><text x="${xs[i]}" y="164" text-anchor="middle">${dateFmt(m.date).replace(' 2026','')}</text>`).join('')}</svg>`}return `<section class="card"><div class="section-title"><h2>Mediciones</h2>${btn('Registrar medición','measurement','secondary')}</div><label>Qué quieres revisar<select id="measure-type">${options(Object.keys(units),measureType)}</select></label>${chart}<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>${esc(measureType)} (${units[measureType]})</th><th>Origen</th></tr></thead><tbody>${items.map(m=>`<tr><td>${dateFmt(m.date)}</td><td>${esc(m.value)}</td><td>${esc(m.source)}</td></tr>`).join('')}</tbody></table></div>${!items.length?'<p class="muted" style="margin-top:18px">No hay mediciones de este tipo.</p>':''}<p class="small muted" style="margin-top:18px">Estos registros no interpretan el estado de salud. Las mediciones clínicas y su interpretación corresponden al profesional.</p></section>`}
function empty(title,text,label,action){return `<div class="empty"><h3>${title}</h3><p>${text}</p>${btn(label,action,'secondary')}</div>`}
function clinic(){return header('MI CLÍNICA','Cuidados que siguen conectados','Solicita una hora y consulta las instrucciones del equipo.',btn('Solicitar hora','booking','primary'))+`<div class="grid"><div><section class="card feature"><div><span class="eyebrow" style="color:#d0e5dc">CLÍNICA ASOCIADA · EJEMPLO</span><h2 style="margin-top:12px">Veterinaria Los Olivos</h2><p>Consultas, controles y seguimiento para perros y gatos.</p><div class="actions">${btn('Solicitar hora','booking','primary')}${btn('Enviar consulta','message')}</div></div></section><section class="card"><h2>Mis solicitudes</h2>${appointmentList(false)}</section><section class="card"><h2>Directorio y servicios</h2><p class="muted small">Información ilustrativa. En el producto real se verificará el centro y la disponibilidad.</p><div class="task"><div class="avatar">LO</div><div class="task-info"><h3>Los Olivos · Consulta general</h3><p class="small muted">Centro asociado de ejemplo</p>${btn('Ver servicios y horarios','directory')}</div></div></section></div><div><section class="card"><h2>Mensajes a la clínica</h2><p class="muted small">Consulta dudas administrativas o pide aclaración de indicaciones. La respuesta no es inmediata.</p>${btn('Nueva consulta','message','secondary')}</section><section class="card"><h2>Necesito atención urgente</h2><p class="muted small">Para atención inmediata, contacta directamente a un centro. Una solicitud o mensaje puede quedar pendiente.</p>${btn('Ver contacto de urgencia','urgent')}</section></div></div>`}
function appointmentList(clinical){const rows=state.appointments;return rows.length?rows.map(a=>`<div class="task"><div class="task-info"><div class="row space"><h3>${esc(a.reason)} · ${esc(petName(a.pet))}</h3><span class="badge ${a.status.includes('Pendiente')?'orange':''}">${esc(a.status)}</span></div><p class="small muted">${dateFmt(a.date)} · ${esc(a.time)} · Tutor: Camilo</p><div class="actions">${clinical&&a.status==='Pendiente de confirmación'?btn('Confirmar fecha y hora','confirm-appointment','primary',`data-id="${a.id}"`):''}${a.status!=='Cancelada'?btn(clinical?'Reprogramar':'Cambiar solicitud','reschedule','',`data-id="${a.id}"`):''}${a.status!=='Cancelada'?btn('Cancelar','cancel-appointment','text-button',`data-id="${a.id}"`):''}</div></div></div>`).join(''):empty('Aún no hay solicitudes',clinical?'Las solicitudes de los tutores aparecerán aquí.':'Elige un motivo y un horario preferido. La clínica confirmará la disponibilidad.',clinical?'Ver experiencia del tutor':'Solicitar hora',clinical?'switch-tutor':'booking')}
function family(){return header('MI FAMILIA','Cuidar juntos, sin duplicar tareas','Define quién puede consultar, registrar o administrar.',btn('Invitar cuidador','invite','primary'))+`<div class="grid"><div><section class="card"><h2>Personas con acceso</h2>${state.family.map(f=>`<div class="task"><div class="avatar mini">${esc(f.name.slice(0,2).toUpperCase())}</div><div class="task-info"><h3>${esc(f.name)}</h3><p class="small muted">${esc(f.role)} · ${esc(f.status)}</p>${f.role!=='Administrador'?`<div class="actions">${btn('Cambiar permisos','permissions','',`data-id="${f.id}"`)}${btn('Revocar acceso','revoke','text-button',`data-id="${f.id}"`)}</div>`:''}</div></div>`).join('')}</section><section class="card"><h2>Actividad compartida</h2>${state.audit.length?state.audit.slice(0,8).map(a=>`<div class="file-item"><p>${esc(a.text)}</p><span class="small muted">${esc(a.author)} · ${esc(a.date)}</span></div>`).join(''):'<p class="muted">Los cuidados realizados y cambios de acceso aparecerán aquí.</p>'}</section></div><div><section class="card"><h2>Permisos claros</h2><p class="small"><strong>Administrador:</strong> administra mascotas, miembros y enlaces.</p><p class="small"><strong>Cuidador:</strong> consulta y registra cuidados y observaciones.</p><p class="small"><strong>Solo lectura:</strong> consulta los datos compartidos.</p></section><section class="card"><h2>Enlaces temporales</h2>${btn('Compartir un resumen','share','secondary')}${state.links.map(l=>`<div class="file-item"><p class="small">${esc(l.label)} · ${l.revoked?'Revocado':'Activo en esta demo'}</p>${!l.revoked?btn('Revocar enlace','revoke-link','text-button',`data-id="${l.id}"`):''}</div>`).join('')}</section><section class="card"><h3>Probar coordinación familiar</h3><label>Registrar cuidados como<select id="actor">${state.family.filter(f=>f.status==='Activo'&&f.role!=='Solo lectura').map(f=>`<option ${actor===f.name?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label></section></div></div>`}
function help(){return header('AYUDA Y EXTRAVÍOS','Una red para volver a casa','Alertas con contacto protegido y una zona aproximada.',btn('Reportar extravío','lost','primary'))+`<div class="grid"><div><section class="card"><h2>Mis alertas</h2>${state.alerts.length?state.alerts.map(a=>`<article class="soft-block"><div class="row space"><h3>${esc(petName(a.pet))}</h3><span class="badge ${a.status==='Encontrada'?'':'orange'}">${esc(a.status)}</span></div><p class="small muted">Última zona reportada: ${esc(a.zone)}<br>${esc(a.date.replace('T',' · '))}</p><div class="actions">${btn('Ver publicación','alert','',`data-id="${a.id}"`)}${a.status!=='Encontrada'?btn('Marcar como encontrada','found','secondary',`data-id="${a.id}"`):''}</div></article>`).join(''):empty('Sin alertas activas','Al reportar un extravío, reutilizaremos el perfil de tu mascota.','Reportar extravío','lost')}</section><section class="card"><div class="section-title"><h2>Alerta de la comunidad</h2><span class="badge neutral">Ejemplo</span></div><h3>Milo · Gato gris</h3><p class="muted small">Última zona reportada: sector Los Olivos.<br>Distancia hasta el último lugar reportado: 2,4 km (ejemplo).</p><p class="small">Esta distancia no indica dónde está el animal ahora.</p><div class="actions">${btn('Informar avistamiento','sighting','secondary', 'data-id="community"')}${btn('Denunciar publicación','report','text-button')}</div></section></div><div><section class="card"><h2>Contacto protegido</h2><p class="small muted">La publicación muestra solo la información que autorizas. Teléfono, dirección, chip e historial permanecen privados.</p></section><section class="card"><h2>Guía de uso</h2>${btn('Cómo compartir documentos','guide-docs','list-link')}${btn('Cómo funcionan las alertas','guide-alerts','list-link')}${btn('Contactar a un centro','urgent','list-link')}</section></div></div>`}
function panel(){const pending=state.appointments.filter(a=>a.status==='Pendiente de confirmación').length;return header('LOS OLIVOS / EQUIPO','Más tiempo para atender','Solicitudes, pacientes y seguimientos en un mismo lugar.',btn('Registrar consulta','clinical-record','primary'))+`<div class="cards"><section class="card"><span class="small muted">Solicitudes por confirmar</span><div class="stat">${pending}</div>${btn('Revisar agenda','agenda','text-button')}</section><section class="card"><span class="small muted">Pacientes en la demo</span><div class="stat">${state.pets.length}</div>${btn('Abrir pacientes','patients','text-button')}</section><section class="card"><span class="small muted">Plan de la clínica</span><div class="stat">${esc(state.plan)}</div>${btn('Ver planes','plans','text-button')}</section></div><div class="grid"><section class="card"><h2>Solicitudes recientes</h2>${appointmentList(true)}</section><div><section class="card"><h2>Seguimientos</h2><p class="muted small">Prepara recordatorios para controles e instrucciones ya registradas.</p>${btn('Configurar automatizaciones','automations','secondary')}</section><section class="card"><h2>Datos con trazabilidad</h2><p class="muted small">Cada consulta conserva autor, fecha y cambios. Los documentos del tutor mantienen su procedencia.</p>${btn('Registrar consulta','clinical-record')}</section></div></div>`}
function agenda(){return header('LOS OLIVOS / AGENDA','Solicitudes y citas','Confirma disponibilidad antes de cerrar la reserva.',btn('Crear cita de ejemplo','booking','primary'))+`<section class="card"><h2>Agenda de solicitudes</h2>${appointmentList(true)}</section><section class="card"><h3>Calendario sin conexión externa</h3><p class="muted small">Esta demo muestra el flujo de solicitud y confirmación. Una versión operativa se conectaría a la agenda real de la clínica.</p></section>`}
function patients(){return header('LOS OLIVOS / PACIENTES','El historial sigue al paciente','Consulta registros y añade instrucciones con autor identificado.',btn('Registrar consulta','clinical-record','primary'))+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Mascota</th><th>Especie</th><th>Tutor</th><th>Acción</th></tr></thead><tbody>${state.pets.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${esc(p.species)}</td><td>Camilo Martínez</td><td>${btn('Abrir ficha','clinical-profile','',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`}
function automations(){return header('LOS OLIVOS / SEGUIMIENTOS','Un cuidado, un siguiente paso','Automatizaciones bajo control de tu equipo.')+`<div class="grid"><div><section class="card"><h2>Recordatorios de citas</h2><p class="muted small">Preparar avisos de una cita confirmada. Los envíos son simulados.</p><label class="check-row"><input type="checkbox" id="auto-visits" ${state.automations.visits?'checked':''}>Activar recordatorios de citas</label><h3 style="margin-top:20px">Seguimiento después de una consulta</h3><label class="check-row"><input type="checkbox" id="auto-followup" ${state.automations.followup?'checked':''}>Preparar un seguimiento para revisión del equipo</label><div class="actions">${btn('Guardar configuración','save-auto','primary')}${btn('Previsualizar mensaje','preview-auto')}</div></section><section class="card"><h2>Registrar indicaciones</h2><p class="muted small">La clínica introduce el plan; el tutor decide cómo recibir sus recordatorios.</p>${btn('Añadir consulta y próximo cuidado','clinical-record','secondary')}</section></div><aside><section class="card"><h2>Antes de enviar</h2><p class="small muted">Comprueba los destinatarios, el consentimiento y la indicación registrada. No se genera una pauta clínica automáticamente.</p></section><section class="card"><h2>Importación e integraciones</h2><p class="small muted">Explora cómo incorporar registros de otro sistema sin reemplazarlo.</p>${btn('Ver flujo de importación','import')}</section></aside></div>`}
function plans(){return header('LOS OLIVOS / PLANES','Un plan para tu equipo','Suscripción por sede. Acceso gratuito para los tutores.')+`<div class="notice">Precios hipotéticos para explorar el modelo de negocio. No se realizará ningún cobro.</div><div class="cards"><section class="card plan"><span class="badge neutral">Piloto</span><h2 style="margin-top:16px">Prueba</h2><div class="stat">CLP 0</div><p class="muted small">Durante el piloto acordado</p><ul><li>Solicitudes de hora</li><li>Perfiles y documentos</li><li>Validación con tu equipo</li></ul>${btn('Seleccionar prueba','choose-plan','', 'data-id="Prueba"')}</section><section class="card plan"><span class="badge">Para comenzar</span><h2 style="margin-top:16px">Inicial</h2><div class="stat">CLP 39.900</div><p class="muted small">Al mes por sede · Impuestos por definir</p><ul><li>Panel de clínica</li><li>Solicitudes y confirmaciones</li><li>Recordatorios básicos</li></ul>${btn('Explorar plan inicial','choose-plan','primary','data-id="Inicial"')}</section><section class="card plan"><span class="badge neutral">Para equipos</span><h2 style="margin-top:16px">Avanzado</h2><div class="stat">CLP 79.900</div><p class="muted small">Al mes por sede · Impuestos por definir</p><ul><li>Funciones del plan inicial</li><li>Seguimientos y equipo</li><li>Informes de actividad</li></ul>${btn('Explorar plan avanzado','choose-plan','', 'data-id="Avanzado"')}</section></div><section class="card"><h3>Condiciones a validar en el piloto</h3><p class="muted small">Mensajería con costo externo e integraciones especiales se cotizarían por separado. El volumen incluido, soporte e impuestos requieren una oferta comercial definitiva.</p><span class="badge">Plan seleccionado en la demo: ${esc(state.plan)}</span></section>`}
const files=new Map();
function addPet(step=1,draft={}){if(step===1){modal('Agregar mascota',`<div class="steps"><span class="active">1 · Lo esencial</span><span>2 · Detalles opcionales</span></div><p class="muted small">Empieza con lo mínimo. Puedes completar el perfil después.</p><form data-form="pet-step1"><div class="form-grid"><label>Nombre<input name="name" required maxlength="50" value="${esc(draft.name||'')}" autocomplete="off"></label><label>Especie<select name="species">${options(['Perro','Gato'],draft.species)}</select></label><label>Edad aproximada (opcional)<input name="age" placeholder="Ej. 2 años o desconocida" value="${esc(draft.age||'')}"></label></div>${formEnd('Continuar')}</form>`)}else{modal('Completar perfil',`<div class="steps"><span>1 · Lo esencial</span><span class="active">2 · Detalles opcionales</span></div><form data-form="pet-step2"><input type="hidden" name="name" value="${esc(draft.name)}"><input type="hidden" name="species" value="${esc(draft.species)}"><input type="hidden" name="age" value="${esc(draft.age)}"><div class="form-grid"><label>Raza o mezcla<input name="breed" placeholder="Opcional"></label><label>Sexo<select name="sex">${options(['No indicado','Macho','Hembra'])}</select></label><label>Esterilización<select name="sterilized">${options(['No indicada','Sí','No'])}</select></label><label>Microchip<input name="chip" placeholder="Opcional · Solo privado"></label></div><label style="margin-top:16px">Foto (opcional)<input type="file" name="photo" accept="image/*"></label>${formEnd('Guardar mascota')}</form>`)} }
function booking(a=null,confirm=false){modal(confirm?'Confirmar fecha y hora':a?'Cambiar solicitud':'Solicitar hora',`<form data-form="booking" data-id="${a?.id||''}" data-confirm="${confirm}"><div class="form-grid"><label>Mascota<select name="pet">${petOptions()}</select></label><label>Motivo<select name="reason">${options(['Control preventivo','Consulta general','Seguimiento'],a?.reason)}</select></label><label>${confirm?'Fecha confirmada':'Fecha preferida'}<input type="date" name="date" required min="${today()}" value="${a?.date||today()}"></label><label>${confirm?'Hora confirmada':'Hora preferida'}<input type="time" name="time" required value="${a?.time||'10:00'}"></label></div><label style="margin-top:16px">Comentario (opcional)<textarea name="comment" placeholder="Información para coordinar la visita">${esc(a?.comment||'')}</textarea></label><div class="notice">${confirm?'La cita quedará confirmada en ambas experiencias de la demo.':'Tu solicitud quedará pendiente hasta que la clínica confirme disponibilidad.'}</div>${formEnd(confirm?'Confirmar cita':'Enviar solicitud')}</form>`);if(a)document.querySelector('#dialog [name=pet]').value=a.pet}
function note(r=null){modal(r?'Editar observación':'Añadir observación',`<form data-form="note" data-id="${r?.id||''}"><label>Título<input name="title" required maxlength="100" value="${esc(r?.title||'')}" placeholder="Ej. Observación en casa"></label><div class="form-grid" style="margin-top:16px"><label>Fecha<input type="date" name="date" required max="${today()}" value="${r?.date||today()}"></label><label>Mascota<select name="pet">${petOptions()}</select></label></div><label style="margin-top:16px">Qué observaste<textarea required name="text">${esc(r?.text||'')}</textarea></label><div class="notice">Aparecerá como observación del tutor, separada de los registros profesionales.</div>${formEnd()}</form>`);if(r)document.querySelector('#dialog [name=pet]').value=r.pet}
function clinicalRecord(){modal('Registrar consulta',`<form data-form="clinical-record"><div class="form-grid"><label>Paciente<select name="pet">${petOptions()}</select></label><label>Fecha de consulta<input name="date" type="date" required max="${today()}" value="${today()}"></label></div><label style="margin-top:16px">Motivo de consulta<input name="title" required placeholder="Ej. Control preventivo"></label><label style="margin-top:16px">Resumen de la consulta<textarea name="text" required></textarea></label><label style="margin-top:16px">Indicaciones y próximo paso<textarea name="plan" placeholder="Indicaciones del profesional"></textarea></label><div class="form-grid"><label>Peso (kg, opcional)<input type="number" min="0.01" step="0.01" name="weight"></label><label>Fecha de próximo cuidado (opcional)<input name="next" type="date" min="${today()}"></label></div><label class="check-row"><input type="checkbox" name="remind">Crear recordatorio del próximo cuidado</label><div class="notice">Autor: Dra. Andrea Torres · Veterinaria Los Olivos. Identidad simulada.</div>${formEnd('Guardar registro')}</form>`)}
function reminder(r=null){modal(r?'Configurar recordatorio':'Crear recordatorio',`<form data-form="reminder" data-id="${r?.id||''}"><label>Nombre del cuidado<input name="title" required maxlength="100" value="${esc(r?.title||'')}" ${r?.source==='clinic'?'readonly':''}></label><div class="form-grid" style="margin-top:16px"><label>Hora<input type="time" name="time" required value="${r?.time||'20:00'}"></label><label>Mascota<select name="pet">${petOptions()}</select></label><label>Inicio<input type="date" name="start" required value="${r?.start||today()}"></label><label>Fin<input type="date" name="end" required value="${r?.end||today()}"></label></div><label class="check-row"><input type="checkbox" name="active" ${!r||r.active?'checked':''}>Recordatorio activo (desmarca para pausar)</label><p class="muted small">Aviso diario a la hora elegida durante el periodo. Si es un tratamiento, usa la pauta recibida del profesional; aquí solo configuras el aviso.</p>${formEnd()}</form>`);if(r)document.querySelector('#dialog [name=pet]').value=r.pet}
function share(){modal('Compartir un resumen',`<form data-form="share"><label>Mascota<select name="pet">${petOptions()}</select></label><fieldset><legend>Qué quieres compartir</legend><label class="check-row"><input type="checkbox" name="profile" checked>Perfil básico</label><label class="check-row"><input type="checkbox" name="history" checked>Historial de consultas</label><label class="check-row"><input type="checkbox" name="docs">Listado de documentos</label></fieldset><div class="form-grid"><label>Nombre del enlace<input name="label" required value="Para mi cuidador"></label><label>Duración<select name="hours">${options(['24 horas','72 horas','7 días'])}</select></label></div><div class="notice">El enlace es una simulación local. No incluye chip, teléfono ni dirección, y podrás revocarlo.</div>${formEnd('Crear enlace de ejemplo')}</form>`)}
let lostDraft=null;
function lost(){modal('Reportar extravío',`<div class="steps"><span class="active">1 · Datos del reporte</span><span>2 · Revisar publicación</span></div><form data-form="lost"><label>Mascota<select name="pet">${petOptions()}</select></label><div class="form-grid" style="margin-top:16px"><label>Última zona donde la viste<input name="zone" required placeholder="Barrio o sector, sin domicilio exacto"></label><label>Cuándo la viste<input name="date" type="datetime-local" required max="${today()}T23:59"></label></div><label style="margin-top:16px">Señas reconocibles<textarea name="details" required placeholder="Collar, colores o marca distintiva"></textarea></label><label style="margin-top:16px">Foto adicional (opcional)<input name="photo" type="file" accept="image/*"></label><label class="check-row"><input name="consent" type="checkbox" required>Autorizo publicar la foto, las señas y la zona aproximada</label><p class="small muted">Tu teléfono, domicilio, chip y ficha clínica quedan privados.</p>${formEnd('Previsualizar alerta')}</form>`)}
function alertBody(a,preview=false){const p=state.pets.find(p=>p.id===a.pet);return `<span class="badge orange">${preview?'Vista previa':'Alerta de ejemplo'} · ${esc(a.status||'Activa')}</span><div class="row" style="margin:18px 0">${avatar(p)}<div><h2>${esc(p.name)}</h2><p class="muted small">${esc(p.species)} · ${esc(p.breed||'Raza o mezcla no indicada')}</p></div></div><p><strong>Última zona reportada:</strong> ${esc(a.zone)}</p><p class="small muted">${esc(a.date.replace('T',' · '))}</p><p>${esc(a.details)}</p>${a.photo?`<img class="pet-image large" src="${esc(a.photo)}" alt="Foto adicional del reporte">`:''}<div class="notice">Contacto protegido. El tutor recibe los avistamientos dentro de la app. No se publica su teléfono.</div>${preview?`<div class="actions">${btn('Corregir datos','lost-back')}${btn('Publicar alerta de ejemplo','publish-lost','primary')}</div>`:`<div class="actions">${btn('Informar avistamiento','sighting','secondary',`data-id="${a.id}"`)}${btn('Preparar cartel imprimible','poster','',`data-id="${a.id}"`)}${btn('Denunciar publicación','report','text-button')}</div>${a.sightings?.length?'<h3 style="margin-top:20px">Avistamientos recibidos</h3>'+a.sightings.map(s=>`<div class="soft-block"><strong>${esc(s.zone)}</strong><p class="small">${esc(s.text)}</p><span class="small muted">${esc(s.date)}</span></div>`).join(''):''}`}`}
function preferences(){modal('Preferencias y accesibilidad',`<form data-form="prefs"><h3>Notificaciones</h3><label>Aplicar a<select name="pet"><option value="all">Todas mis mascotas</option>${petOptions()}</select></label><label class="check-row"><input type="checkbox" name="push" ${state.prefs.push?'checked':''}>Avisos en la app</label><label class="check-row"><input type="checkbox" name="email" ${state.prefs.email?'checked':''}>Correo electrónico</label><label class="check-row"><input type="checkbox" name="quiet" ${state.prefs.quiet?'checked':''}>Silenciar avisos generales de 22:00 a 08:00</label><p class="small muted">Los avisos de cuidados se configuran por separado. En esta demo no se envían notificaciones reales.</p><h3 style="margin-top:20px">Lectura y apariencia</h3><label class="check-row"><input type="checkbox" name="contrast" ${state.prefs.contrast?'checked':''}>Aumentar contraste</label><label class="check-row"><input type="checkbox" name="dark" ${state.prefs.dark?'checked':''}>Apariencia oscura</label><label>Tamaño de texto<select name="scale">${['100','125','150','200'].map(x=>`<option value="${x}" ${state.prefs.scale===x?'selected':''}>${x}%</option>`).join('')}</select></label><div class="notice">Los datos de ejemplo se guardan únicamente en este navegador. Puedes borrarlos con «Reiniciar demo».</div>${formEnd()}</form>`);document.querySelector('#dialog [name=pet]').value=state.prefs.pet}
function exportData(){download('omp-'+pet().name.toLowerCase()+'-datos.json',JSON.stringify({pet:pet(),records:state.records.filter(r=>r.pet===selectedPet),documents:state.documents.filter(d=>d.pet===selectedPet),measurements:state.measurements.filter(m=>m.pet===selectedPet)},null,2),'application/json');toast('Datos exportados. Los originales cargados no se incluyen en el archivo.')}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printDoc(title,body){const w=window.open('','_blank');if(!w){toast('Permite abrir una ventana para preparar la impresión.');return}w.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font:16px/1.6 system-ui;color:#173a34;max-width:800px;margin:40px auto;padding:20px}h1{font-size:30px}section{border-top:1px solid #ddd;padding:18px 0}button{padding:12px;font:inherit}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Imprimir o guardar como PDF</button><h1>${esc(title)}</h1><p>OMP · Documento de demostración, sin validez clínica</p>${body}</body></html>`);w.document.close()}
function recordDetail(id){const r=state.records.find(r=>r.id===id);modal(r.title,`<span class="badge ${r.source==='clinic'?'':'neutral'}">${r.source==='clinic'?'Registrado por la clínica':'Añadido por el tutor'}</span><p class="muted small" style="margin-top:14px">${dateFmt(r.date)} · ${esc(r.author)}</p><h3>Resumen</h3><p>${esc(r.text)}</p>${r.plan?`<h3>Próximo paso</h3><p>${esc(r.plan)}</p>`:''}${r.weight?`<p><strong>Peso:</strong> ${esc(r.weight)} kg</p>`:''}<div class="actions">${btn('Ver cambios','audit-record','',`data-id="${id}"`)}${btn('Imprimir registro','print-record','secondary',`data-id="${id}"`)}${r.source==='clinic'&&role==='clinic'?btn('Corregir registro','edit-clinical','',`data-id="${id}"`):''}</div>`)}
const actions={
 'add-pet':()=>addPet(),profile:()=>{tab='resumen';go('mascotas')},'select-pet':id=>{selectedPet=id;query='';render()},tab:id=>{tab=id;render();document.getElementById('pet-section-content')?.scrollIntoView({block:'start',behavior:'instant'})},booking:()=>booking(),appointments:()=>go('clinica'),family:()=>go('familia'),lost,share,note:()=>note(),'edit-note':id=>note(state.records.find(r=>r.id===id)),record:recordDetail,
 'audit-record':id=>{const r=state.records.find(r=>r.id===id);modal('Historial de cambios',r.changes.map(c=>`<div class="file-item"><h3>${esc(c.text)}</h3><p class="small muted">${esc(c.author)} · ${esc(c.date)}</p></div>`).join(''))},
 'edit-clinical':id=>{const r=state.records.find(r=>r.id===id);modal('Corregir registro profesional',`<form data-form="edit-clinical" data-id="${id}"><label>Resumen<textarea name="text" required>${esc(r.text)}</textarea></label><label>Indicaciones<textarea name="plan">${esc(r.plan)}</textarea></label><label>Motivo de la corrección<input name="reason" required></label><div class="notice">Se conserva la versión anterior en el historial de cambios.</div>${formEnd('Guardar corrección')}</form>`)},
 'edit-pet':()=>modal('Editar perfil',`<form data-form="edit-pet"><div class="form-grid"><label>Nombre<input name="name" required value="${esc(pet().name)}"></label><label>Raza o mezcla<input name="breed" value="${esc(pet().breed)}"></label><label>Edad aproximada<input name="age" value="${esc(pet().age)}"></label><label>Sexo<select name="sex">${options(['No indicado','Macho','Hembra'],pet().sex)}</select></label><label>Esterilización<select name="sterilized">${options(['No indicada','Sí','No'],pet().sterilized)}</select></label><label>Chip (privado)<input name="chip" value="${esc(pet().chip)}"></label></div>${formEnd()}</form>`),
 complete:id=>{const r=state.reminders.find(r=>r.id===(id||'care1'));if(!r||r.done)return toast('Este cuidado ya está registrado.');if(!state.family.some(f=>f.name===actor&&f.status==='Activo'&&f.role!=='Solo lectura'))return toast('Este miembro no tiene permiso para registrar cuidados.');r.done=true;r.by=actor;audit(`Cuidado realizado para ${petName(r.pet)}: ${r.title}`);persist('Cuidado registrado. La familia puede ver quién lo realizó.');render()},
 reminder:id=>reminder(state.reminders.find(r=>r.id===id)),'new-reminder':()=>reminder(),
 measurement:()=>modal('Registrar medición',`<form data-form="measurement"><div class="form-grid"><label>Tipo<select name="type">${options(['Peso','Temperatura','Frecuencia cardíaca','Respiración'],measureType)}</select></label><label>Valor<input type="number" name="value" required min="0.01" max="10000" step="0.01"></label><label>Fecha<input type="date" name="date" required max="${today()}" value="${today()}"></label></div><p class="muted small" style="margin-top:16px">Unidades: peso en kg, temperatura en °C, frecuencia cardíaca en lat/min y respiración en resp/min.</p>${formEnd()}</form>`),
 upload:()=>modal('Añadir documento',`<form data-form="upload"><label>Archivo original<input type="file" name="file" required accept=".pdf,image/*"></label><label style="margin-top:16px">Nombre del documento<input name="name" required placeholder="Ej. Resultado de examen"></label><div class="notice">Quedará como añadido por el tutor, sin validar. El archivo se consulta en este navegador durante esta sesión.</div>${formEnd('Añadir archivo')}</form>`),
 document:id=>{const d=state.documents.find(d=>d.id===id);if(d.local){const file=files.get(id);if(file){const url=URL.createObjectURL(file);const w=window.open(url,'_blank','noopener');if(!w)toast('Permite ventanas para abrir el documento.');setTimeout(()=>URL.revokeObjectURL(url),60000)}else modal('Original no disponible',`<p>El archivo solo estuvo disponible en la sesión en que se seleccionó.</p><p class="muted small">Vuelve a seleccionar el original para consultarlo.</p>${btn('Añadir documento','upload','primary')}`)}else modal('Constancia de ejemplo',`<span class="badge">Emisor identificado en la demo</span><h3 style="margin-top:18px">${esc(d.name)}</h3><p>Mascota: ${esc(petName(d.pet))}<br>Emisor: ${esc(d.issuer)}<br>Fecha: ${dateFmt(d.date)}</p><p class="small muted">No se representa una firma ni se certifica un acto clínico real.</p><div class="actions">${btn('Consultar procedencia','verify','',`data-id="${id}"`)}${btn('Imprimir ejemplo','print-certificate','secondary',`data-id="${id}"`)}</div>`)},
 verify:id=>{const d=state.documents.find(d=>d.id===id);modal('Procedencia del documento',`<h3>${esc(d.name)}</h3><div class="status-line"><span>Emisor</span><strong>${esc(d.issuer)}</strong></div><div class="status-line"><span>Identificador de demo</span><strong>OMP-${esc(id).toUpperCase()}</strong></div><div class="status-line"><span>Fecha</span><strong>${dateFmt(d.date)}</strong></div><div class="notice warning">Validación simulada. La versión operativa consultaría el documento original y la identidad del emisor; esta constancia no tiene validez.</div>`)},
 export:exportData,'print-summary':()=>printDoc('Resumen de '+pet().name,`<p>${esc(pet().species)} · ${esc(pet().breed)} · ${esc(pet().age)}</p>${state.records.filter(r=>r.pet===selectedPet).map(r=>`<section><h2>${esc(r.title)}</h2><p>${dateFmt(r.date)} · ${esc(r.author)} · ${r.source==='clinic'?'Clínica':'Tutor'}</p><p>${esc(r.text)}</p><p>${esc(r.plan)}</p></section>`).join('')}`),
 'print-record':id=>{const r=state.records.find(r=>r.id===id);printDoc(r.title,`<p>${dateFmt(r.date)} · ${esc(r.author)}</p><p>${esc(r.text)}</p><p>${esc(r.plan)}</p>`)},
 'print-certificate':id=>{const d=state.documents.find(d=>d.id===id);printDoc(d.name,`<p>${esc(petName(d.pet))} · ${dateFmt(d.date)} · ${esc(d.issuer)}</p><p>Ejemplo de presentación. No certifica una vacunación real.</p>`)},
 invite:()=>modal('Invitar cuidador',`<form data-form="invite"><label>Nombre<input name="name" required maxlength="70"></label><label style="margin-top:16px">Correo<input name="email" required type="email"></label><label style="margin-top:16px">Permiso<select name="role">${options(['Cuidador','Solo lectura'])}</select></label><div class="notice">La invitación se simula; no enviaremos correo. Podrás activarla desde esta demo.</div>${formEnd('Crear invitación')}</form>`),
 permissions:id=>{const f=state.family.find(f=>f.id===id);modal('Permisos de '+f.name,`<form data-form="permissions" data-id="${id}"><label>Permiso<select name="role">${options(['Cuidador','Solo lectura'],f.role)}</select></label><label class="check-row"><input type="checkbox" name="active" ${f.status==='Activo'?'checked':''}>Acceso activo en la demo</label>${formEnd()}</form>`)},
 revoke:id=>{const f=state.family.find(f=>f.id===id);modal('Revocar acceso',`<p>${esc(f.name)} perderá el acceso a la familia. Puedes volver a activarlo desde sus permisos.</p>${btn('Revocar acceso','confirm-revoke','danger',`data-id="${id}"`)}`)},'confirm-revoke':id=>{const f=state.family.find(f=>f.id===id);f.status='Revocado';if(actor===f.name)actor='Camilo Martínez';audit('Acceso revocado para '+f.name);persist('Acceso revocado.');close();render()},
 'revoke-link':id=>{state.links.find(l=>l.id===id).revoked=true;audit('Enlace compartido revocado');persist('Enlace revocado.');render()},
 'preview-shared':id=>{const l=state.links.find(l=>l.id===id);if(l.revoked)return toast('El enlace está revocado.');modal('Vista del destinatario',`<span class="badge">Solo lectura · ${esc(l.hours)}</span><h3 style="margin-top:18px">${esc(petName(l.pet))}</h3>${l.profile?`<p>Perfil básico: ${esc(state.pets.find(p=>p.id===l.pet).species)}</p>`:''}${l.history?state.records.filter(r=>r.pet===l.pet).map(r=>`<div class="soft-block"><strong>${esc(r.title)}</strong><p class="small">${esc(r.text)}</p></div>`).join(''):''}${l.docs?state.documents.filter(d=>d.pet===l.pet).map(d=>`<p class="small">Documento: ${esc(d.name)}</p>`).join(''):''}<p class="small muted">Vista local simulada, sin datos de contacto ni chip.</p>`)},
 message:()=>modal('Enviar consulta a la clínica',`<form data-form="message"><label>Mascota<select name="pet">${petOptions()}</select></label><label style="margin-top:16px">Tu consulta<textarea name="text" required placeholder="¿En qué podemos ayudarte?"></textarea></label><div class="notice warning">La respuesta no es inmediata. Para atención urgente, contacta directamente a un centro.</div>${formEnd('Enviar consulta de ejemplo')}</form>`),
 directory:()=>modal('Los Olivos · Servicios y horarios',`<span class="badge neutral">Centro de ejemplo</span><h3 style="margin-top:18px">Consulta general y controles</h3><p class="muted">Lunes a viernes · 09:00 a 18:00 (horario ilustrativo)</p><p>Las solicitudes requieren confirmación del equipo.</p>${btn('Solicitar hora','booking','primary')}`),
 urgent:()=>modal('Contacto de atención urgente',`<p>Busca un centro veterinario con atención inmediata y confirma su disponibilidad por teléfono.</p><div class="notice warning">No se muestra un número ficticio como contacto de emergencia. Los centros y teléfonos deben verificarse antes de operar.</div><p class="small muted">Esta demo no ofrece atención veterinaria ni contacta a un servicio de urgencias.</p>`),
 alert:id=>modal('Alerta de extravío',alertBody(state.alerts.find(a=>a.id===id))),
 'lost-back':()=>{lost();const f=document.querySelector('[data-form=lost]');for(const key of ['pet','zone','date','details'])f.elements[key].value=lostDraft[key];f.elements.consent.checked=true},
 'publish-lost':()=>{if(!lostDraft)return;state.alerts.unshift({...lostDraft,id:crypto.randomUUID(),status:'Activa',sightings:[]});audit('Alerta de extravío creada para '+petName(lostDraft.pet));persist('Alerta publicada en la demo. No se ha difundido fuera de este navegador.');close();go('ayuda');render();lostDraft=null},
 found:id=>modal('Marcar como encontrada',`<p>La alerta se cerrará y dejará de solicitar avistamientos.</p>${btn('Confirmar que fue encontrada','confirm-found','primary',`data-id="${id}"`)}`),'confirm-found':id=>{state.alerts.find(a=>a.id===id).status='Encontrada';audit('Alerta cerrada: mascota encontrada');persist('Alerta cerrada.');close();render()},
 sighting:id=>modal('Informar avistamiento',`<form data-form="sighting" data-id="${id}"><label>Zona del avistamiento<input name="zone" required></label><label style="margin-top:16px">Qué viste<textarea name="text" required placeholder="Describe el animal y cuándo lo viste"></textarea></label><label class="check-row"><input name="consent" type="checkbox" required>Acepto compartir este reporte con el tutor</label>${formEnd('Enviar avistamiento de ejemplo')}</form>`),
 report:()=>modal('Denunciar publicación',`<form data-form="report"><label>Motivo<select name="reason">${options(['Información falsa','Uso de datos personales','Contenido inapropiado','Otro'])}</select></label><label style="margin-top:16px">Detalle (opcional)<textarea name="text"></textarea></label>${formEnd('Enviar denuncia de ejemplo')}</form>`),
 poster:id=>{const a=state.alerts.find(a=>a.id===id);printDoc('Se busca a '+petName(a.pet),`<p>Última zona reportada: ${esc(a.zone)}</p><p>${esc(a.details)}</p><p>Reporte de demostración. El contacto real se habilitaría mediante un enlace protegido.</p>`)},
 'guide-docs':()=>modal('Compartir documentos',`<p>En el perfil de tu mascota, abre «Documentos» y añade el original. Usa «Compartir» para elegir el contenido y la duración del acceso.</p><p>Los archivos del tutor mantienen esa procedencia hasta que la clínica los revise.</p>${btn('Ir a documentos','go-docs','primary')}`),'go-docs':()=>{close();tab='documentos';go('mascotas');render()},
 'guide-alerts':()=>modal('Cómo funcionan las alertas',`<p>Elige tu mascota, indica la última zona reportada y revisa la información antes de publicar.</p><p>Recibe avistamientos mediante contacto protegido. Al encontrarla, cierra la alerta.</p>${btn('Crear reporte','lost','primary')}`),
 wellness:()=>modal('Registrar actividad de bienestar',`<form data-form="wellness"><label>Actividad<select name="activity">${options(['Tiempo de juego compartido','Paseo acompañado','Enriquecimiento en casa'])}</select></label><p class="muted small" style="margin-top:16px">Registro personal, sin pautas ni objetivos obligatorios. Adapta las actividades a las indicaciones del profesional.</p>${formEnd('Registrar actividad')}</form>`),
 agenda:()=>go('agenda'),patients:()=>go('pacientes'),plans:()=>go('planes'),automations:()=>go('automatizaciones'),'switch-tutor':()=>switchRole('tutor'),'clinical-record':clinicalRecord,
 'clinical-profile':id=>{selectedPet=id;modal('Ficha de '+petName(id),`${state.records.filter(r=>r.pet===id).map(r=>`<div class="file-item"><span class="badge ${r.source==='tutor'?'neutral':''}">${r.source==='clinic'?'Clínica':'Tutor'}</span><h3 style="margin-top:10px">${esc(r.title)}</h3><p class="small muted">${dateFmt(r.date)} · ${esc(r.author)}</p><p>${esc(r.text)}</p>${btn('Ver registro','record','',`data-id="${r.id}"`)}</div>`).join('')||'<p>Sin registros todavía.</p>'}<div class="actions" style="margin-top:20px">${btn('Registrar consulta','clinical-record','primary')}</div>`)},
 'confirm-appointment':id=>booking(state.appointments.find(a=>a.id===id),true),reschedule:id=>booking(state.appointments.find(a=>a.id===id)),
 'cancel-appointment':id=>modal('Cancelar solicitud o cita',`<p>La cancelación quedará visible para el tutor y la clínica.</p>${btn('Confirmar cancelación','confirm-cancel','danger',`data-id="${id}"`)}`),'confirm-cancel':id=>{state.appointments.find(a=>a.id===id).status='Cancelada';audit('Solicitud o cita cancelada');persist('Cancelación registrada.');close();render()},
 'save-auto':()=>{state.automations.visits=document.getElementById('auto-visits').checked;state.automations.followup=document.getElementById('auto-followup').checked;persist('Configuración guardada. No se envían mensajes reales.')},
 'preview-auto':()=>modal('Vista previa del seguimiento',`<span class="badge neutral">Mensaje de ejemplo</span><div class="soft-block">Hola, Camilo. Puedes revisar las indicaciones de la última consulta de Luke y coordinar el próximo control con Los Olivos.</div><p class="muted small">Destinatario: tutor con consentimiento. Canal: preferencia del tutor. El equipo revisa antes de activar un seguimiento.</p>`),
 import:()=>modal('Importar registros',`<form data-form="import"><p class="muted small">Explora una carga asistida. No está conectada con un software de gestión.</p><label>Archivo de origen<input name="file" type="file" required accept=".csv,.json"></label><label style="margin-top:16px">Sistema de origen<input name="source" required placeholder="Nombre del sistema"></label>${formEnd('Revisar importación')}</form>`),
 'choose-plan':id=>modal('Explorar plan '+id,`<p>Seleccionarás <strong>${esc(id)}</strong> para esta demo. No se solicitan datos de pago ni se realiza un cobro.</p>${btn('Seleccionar plan de ejemplo','confirm-plan','primary',`data-id="${id}"`)}`),'confirm-plan':id=>{state.plan=id;persist('Plan de ejemplo seleccionado.');close();render()},cancel:close,
};
function switchRole(value){role=value;document.getElementById('role').value=value;route=value==='clinic'?'panel':'hoy';location.hash=route;render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=actions[b.dataset.action];if(action)action(b.dataset.id)});
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const fd=new FormData(f);const v=Object.fromEntries(fd.entries());const type=f.dataset.form,id=f.dataset.id;let success=true;
 if(type==='pet-step1'){addPet(2,v);return}
 if(type==='pet-step2'){const photo=fd.get('photo');if(photo?.size>8*1024*1024)return toast('Elige una imagen de menos de 8 MB.');const p={...v,id:crypto.randomUUID(),photo:photo?.size?URL.createObjectURL(photo):''};state.pets.push(p);selectedPet=p.id;audit('Mascota añadida: '+p.name);tab='resumen';route='mascotas';location.hash='mascotas'}
 else if(type==='edit-pet'){Object.assign(pet(),v);audit('Perfil de '+pet().name+' actualizado')}
 else if(type==='booking'){if(v.date<today())return toast('Elige una fecha actual o futura.');if(id){const a=state.appointments.find(a=>a.id===id);Object.assign(a,v,{status:f.dataset.confirm==='true'?'Confirmada':'Pendiente de confirmación'})}else state.appointments.push({...v,id:crypto.randomUUID(),status:state.offline?'Pendiente de envío':'Pendiente de confirmación'});audit('Solicitud de hora actualizada para '+petName(v.pet))}
 else if(type==='note'){if(id){const r=state.records.find(r=>r.id===id);r.changes.push({date:stamp(),author:actor,text:'Versión anterior: '+r.text});Object.assign(r,v)}else state.records.push({...v,id:crypto.randomUUID(),type:'Observación',source:'tutor',author:actor,plan:'',changes:[{date:stamp(),author:actor,text:'Anotación creada'}]});audit('Observación registrada para '+petName(v.pet))}
 else if(type==='clinical-record'){if(fd.has('remind')&&!v.next)return toast('Indica una fecha de próximo cuidado para crear el recordatorio.');const r={...v,id:crypto.randomUUID(),type:'Consulta',source:'clinic',author:'Dra. Andrea Torres',changes:[{date:stamp(),author:'Dra. Andrea Torres',text:'Registro creado'}]};state.records.push(r);if(v.weight)state.measurements.push({pet:v.pet,date:v.date,type:'Peso',value:Number(v.weight),unit:'kg',source:'Clínica'});if(fd.has('remind')&&v.next)state.reminders.push({id:crypto.randomUUID(),pet:v.pet,title:'Próximo cuidado: '+v.title,time:'10:00',start:v.next,end:v.next,active:true,done:false,by:'',source:'clinic'});audit('Consulta registrada para '+petName(v.pet))}
 else if(type==='edit-clinical'){const r=state.records.find(r=>r.id===id);r.changes.push({date:stamp(),author:'Dra. Andrea Torres',text:'Corrección: '+v.reason+'. Versión anterior: '+r.text+' / '+r.plan});r.text=v.text;r.plan=v.plan;audit('Registro profesional corregido: '+v.reason)}
 else if(type==='reminder'){if(v.end<v.start)return toast('La fecha de fin debe ser igual o posterior al inicio.');if(id){const r=state.reminders.find(r=>r.id===id);Object.assign(r,v,{active:fd.has('active')})}else state.reminders.push({...v,id:crypto.randomUUID(),active:fd.has('active'),done:false,by:'',source:'tutor'});audit('Recordatorio configurado para '+petName(v.pet))}
 else if(type==='measurement'){const units={Peso:'kg',Temperatura:'°C','Frecuencia cardíaca':'lat/min',Respiración:'resp/min'};state.measurements.push({...v,pet:selectedPet,value:Number(v.value),unit:units[v.type],source:role==='clinic'?'Clínica':'Tutor'});measureType=v.type;audit('Medición registrada para '+pet().name)}
 else if(type==='upload'){const file=fd.get('file');if(file.size>20*1024*1024)return toast('Elige un archivo de menos de 20 MB.');const d={id:crypto.randomUUID(),pet:selectedPet,name:v.name,issuer:'Añadido por el tutor',date:today(),verified:false,local:true};files.set(d.id,file);state.documents.push(d);audit('Documento añadido por el tutor')}
 else if(type==='share'){if(!fd.has('profile')&&!fd.has('history')&&!fd.has('docs'))return toast('Selecciona al menos un contenido para compartir.');const l={id:crypto.randomUUID(),pet:v.pet,label:v.label,hours:v.hours,profile:fd.has('profile'),history:fd.has('history'),docs:fd.has('docs'),revoked:false};state.links.push(l);persist();modal('Enlace de ejemplo preparado',`<p>Comparte ${esc(l.label)} · ${esc(l.hours)}</p><div class="link-output">omp.demo/resumen/${l.id.slice(0,8)}</div><p class="small muted" style="margin-top:16px">No es un enlace público operativo. Puedes explorar aquí lo que vería el destinatario.</p><div class="actions">${btn('Ver como destinatario','preview-shared','primary',`data-id="${l.id}"`)}${btn('Cerrar','cancel')}</div>`);return}
 else if(type==='invite'){state.family.push({id:crypto.randomUUID(),name:v.name,email:v.email,role:v.role,status:'Invitación pendiente'});audit('Invitación preparada para '+v.name)}
 else if(type==='permissions'){const member=state.family.find(f=>f.id===id);member.role=v.role;member.status=fd.has('active')?'Activo':'Revocado';if(actor===member.name&&(member.status!=='Activo'||member.role==='Solo lectura'))actor='Camilo Martínez';audit('Permisos actualizados para '+member.name)}
 else if(type==='lost'){const photo=fd.get('photo');if(photo?.size>8*1024*1024)return toast('Elige una foto de menos de 8 MB.');lostDraft={pet:v.pet,zone:v.zone,date:v.date,details:v.details,photo:photo?.size?URL.createObjectURL(photo):''};modal('Revisar publicación',`<div class="steps"><span>1 · Datos del reporte</span><span class="active">2 · Revisar publicación</span></div>${alertBody(lostDraft,true)}`);return}
 else if(type==='sighting'){if(id!=='community'){const a=state.alerts.find(a=>a.id===id);a.sightings.push({zone:v.zone,text:v.text,date:stamp()})}audit('Avistamiento recibido');persist('Avistamiento registrado en la demo.');close();render();return}
 else if(type==='prefs'){for(const key of ['push','email','quiet','contrast','dark'])state.prefs[key]=fd.has(key);state.prefs.scale=v.scale;state.prefs.pet=v.pet}
 else if(type==='wellness'){state.wellness++;audit('Actividad registrada: '+v.activity)}
 else if(type==='import'){const file=fd.get('file');modal('Revisión de importación',`<p>Archivo: ${esc(file.name)}<br>Origen: ${esc(v.source)}</p><div class="notice warning">Revisión ilustrativa. No se ha leído ni importado el contenido del archivo.</div><p class="small">Una integración operativa verificará campos, pacientes, duplicados y autoría antes de incorporar registros.</p>`);return}
 else if(type==='message'||type==='report'){audit(type==='message'?'Consulta a la clínica preparada':'Denuncia preparada');persist(type==='message'?'Consulta registrada en la demo. No se ha enviado a una clínica.':'Denuncia registrada en la demo. No se ha enviado a un moderador.');close();render();return}
 else success=false;
 if(success){persist(state.offline?'Cambio guardado localmente, pendiente de sincronización simulada.':'Cambios guardados en la demo.');close();render()}
});
document.addEventListener('change',e=>{if(e.target.id==='history-filter'){recordFilter=e.target.value;render()}if(e.target.id==='actor'){actor=e.target.value;toast('Los próximos cuidados se registrarán como '+actor)}if(e.target.id==='measure-type'){measureType=e.target.value;render();const details=document.querySelector('.measurements-details');if(details)details.open=true}if(e.target.id==='pet-switch'){selectedPet=e.target.value;query='';recordFilter='all';tab='resumen';render();window.scrollTo({top:0,behavior:'instant'})}});
document.addEventListener('input',e=>{if(e.target.id==='history-search'){query=e.target.value;const pos=e.target.selectionStart;render();const input=document.getElementById('history-search');input.focus();input.setSelectionRange(pos,pos)}});
document.getElementById('role').onchange=e=>switchRole(e.target.value);
document.getElementById('close-dialog').onclick=close;
document.getElementById('preferences').onclick=preferences;
document.getElementById('connection').onclick=()=>{state.offline=!state.offline;if(!state.offline){state.appointments.filter(a=>a.status==='Pendiente de envío').forEach(a=>a.status='Pendiente de confirmación');state.queue=0}persist(state.offline?'Modo sin conexión de ejemplo activado.':'Reconexión simulada: cambios locales disponibles en la demo.');render()};
document.getElementById('reset').onclick=()=>modal('Reiniciar demo',`<p>Se borrarán los cambios de ejemplo guardados en este navegador y se restaurarán los datos iniciales.</p>${btn('Borrar cambios y reiniciar','reset-confirm','danger')}`);
actions['reset-confirm']=()=>{state=seed();selectedPet='luke';actor='Camilo Martínez';tab='resumen';query='';files.clear();persist('Demo reiniciada.');close();switchRole('tutor')};
document.getElementById('credits').onclick=()=>modal('Créditos y alcance',`<p>OMP · Prototipo basado en el proyecto OMPV1 y su rediseño.</p><p class="small">Foto: <a href="https://commons.wikimedia.org/wiki/File:Smooth_Dachshund_red_and_tan_portrait.jpg" target="_blank" rel="noopener">Raven Underwood / Wikimedia Commons</a>, <a href="https://creativecommons.org/licenses/by/2.0/" target="_blank" rel="noopener">CC BY 2.0</a>. Encuadre adaptado al perfil.</p><p class="small muted">Clínica, profesionales y registros son ejemplos. Reservas, verificación, mensajería, enlaces, pagos e importación se simulan. No hay autenticación de roles ni controles de acceso reales en esta demo. Los datos se conservan localmente; evita introducir datos reales sensibles.</p>`);
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'hoy';render();window.scrollTo({top:0,behavior:'instant'})});
window.addEventListener('offline',()=>toast('El navegador perdió conexión. Los datos guardados siguen disponibles en la sesión.'));
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_omp_demo_state',description:'Lee las mascotas y solicitudes de ejemplo de OMP, sin modificar datos.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({role,route,pets:state.pets.map(p=>({id:p.id,name:p.name})),appointments:state.appointments.map(a=>({id:a.id,status:a.status}))})},{name:'navigate_omp_demo',description:'Abre una sección del prototipo OMP dentro del rol actual. No realiza reservas ni envíos.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['hoy','mascotas','clinica','familia','ayuda','panel','agenda','pacientes','automatizaciones','planes']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const permitted=role==='clinic'?['panel','agenda','pacientes','automatizaciones','planes']:['hoy','mascotas','clinica','familia','ayuda'];if(!input||!permitted.includes(input.section))throw new Error('Sección no disponible para el rol actual');route=input.section;render();location.hash=route;return {role,route}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
